import{_ as r,l as n,o as a,c as o,v as l,p as d,x as t,d as s,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const y=JSON.parse('{"title":"Hindley–Milner 算法 W","description":"","frontmatter":{"title":"Hindley–Milner 算法 W","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hindley-milner-w.md","filePath":"cs/hindley-milner-w.md","lastUpdated":1789023840000}'),h={name:"cs/hindley-milner-w.md"};function m(_,e,u,f,T,b){const i=n("Mermaid");return a(),o("div",null,[e[1]||(e[1]=l('<h1 id="hindley–milner-算法-w" tabindex="-1">Hindley–Milner 算法 W <a class="header-anchor" href="#hindley–milner-算法-w" aria-label="Permalink to &quot;Hindley–Milner 算法 W&quot;">​</a></h1><div class="epigraph"><p>在 let 多态的核心语言上，算法 W 用合一求出主类型方案；失败则没有简单类型实例。</p><footer>—— 据 Hindley, 1969；Milner, 1978；Damas and Milner, Principal Type-Schemes for Functional Programs, 1982；Pierce TAPL 整理</footer></div><p>上一课<a href="/cs/simply-typed-lambda">简单类型 λ</a>要人写满 \\(\\tau\\to\\tau&#39;\\)。主干<a href="/cs/type-inference">类型推导直觉</a>已给合一的形状。缺口是<strong>算法 W</strong>：对 Mini-ML 项具体怎么推广、怎么实例化、occurs check 卡在哪。本课钉伪代码级步骤，不把 System F 的类型 lambda 写进主干。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>STLC 的恒等须写成 \\(\\lambda x:\\tau.x\\)。ML：<code>id</code> 的类型是 \\(\\forall \\alpha.\\,\\alpha\\to\\alpha\\)，在 <code>id 1</code> 与 <code>id true</code> 各实例化一次。W：给项与环境，返回替换与类型（或方案）。应用处合一；<code>let x = e1 in e2</code> 先推 \\(e_1\\)，再把不被环境提到的变量量化。缺口是<strong>推广时机</strong>，不是再定义箭头。</p><p>与主干直觉课的差：本课把 let 绑定的 \\(\\mathrm{Gen}\\) 写清楚，并点名下一课的值限制——W 在可变引用上会推得过宽。</p><h3 id="主类型不是「任意超类型」" tabindex="-1">主类型不是「任意超类型」 <a class="header-anchor" href="#主类型不是「任意超类型」" aria-label="Permalink to &quot;主类型不是「任意超类型」&quot;">​</a></h3><p>principal type scheme 是最一般的可量化结果。子类型后课才有宽化；HM 合一是对称的，没有「int 是 object」。</p><p><span class="marginnote">Damas–Milner 1982。算法 W 与 J、M 是同一理论的不同陈述。Pierce TAPL 第 22 章。本课不证完备性全文。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(\\mathrm{W}(\\Gamma,e)\\)：变量则实例化方案；\\(\\lambda\\) 则新鲜 \\(\\alpha\\)，推体；应用则推两端，合一左件与 \\(\\alpha\\to\\beta\\)；let 则 \\(\\mathrm{Gen}\\)。合一：变量绑到项（先 occurs），箭头结构递归。</p>',11)),(a(),d(p,null,{default:t(()=>[c(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E9%A1%B9%22%5D%20--%3E%20W%5B%22%E7%AE%97%E6%B3%95%20W%22%5D%0A%20%20W%20--%3E%20U%5B%22%E5%90%88%E4%B8%80%22%5D%0A%20%20U%20--%3E%20SCH%5B%22%E7%B1%BB%E5%9E%8B%E6%96%B9%E6%A1%88%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<p>实现：替换用并查集路径压缩（Appel / 现代编译器常见）。错误信息：合一失败时保留两侧类型，指向应用结点——接前端诊断，不在此展开。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>复杂度：合一近线性摊还；最坏病理项可指数（类型大小）。实用 ML 够用。没有 let 只有 λ 的核心是 STLC 推导，主类型仍存在但不量化。</p><p>不要把 W 当重载决议：<code>+</code> 的多实现是类型类或特设重载，后课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写值限制的全部反例，下一课专门收。不引入高阶多态（System F 的推断不可判定，点名）。后课默认：HM = let 泛化 + 合一主类型。下一课 let 多态与值限制。</p><p>也不把 Haskell 的扩展（GADT、TypeFamilies）当 W 的一部分。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>W：合一 + let 处 \\(\\mathrm{Gen}\\)，得主类型方案。</li><li>应用处实例化；λ 参数用新鲜变量。</li><li>occurs check 拒绝无限类型。</li><li>出处：Hindley；Milner, 1978；Damas and Milner, 1982；Pierce TAPL。</li></ul>',9))])}const M=r(h,[["render",m]]);export{y as __pageData,M as default};
